import limited_client as robot, numpy as np

def qmul(a,b):
 w,x,y,z=a;W,X,Y,Z=b
 return np.array([w*W-x*X-y*Y-z*Z,w*X+x*W+y*Z-z*Y,w*Y-x*Z+y*W+z*X,w*Z+x*Y-y*X+z*W])
def qinv(q): return np.array([q[0],-q[1],-q[2],-q[3]])
def rotvec(q):
 if q[0]<0:q=-q
 q=q/np.linalg.norm(q); ang=2*np.arctan2(np.linalg.norm(q[1:]),q[0]);return q[1:]*(ang/max(np.linalg.norm(q[1:]),1e-9))
r=robot.observe()['robot'];q0=np.array(r['joint_positions']);x0=np.array(r['tcp_position']);R0=np.array(r['tcp_quaternion_wxyz']);print('base',np.round(q0,3),np.round(x0,3),np.round(R0,3))
for j in range(7):
 q=q0.copy();q[j]+=.04;robot.step(list(q)+[.04,.04]);r=robot.observe()['robot'];dq=np.array(r['joint_positions'])-q0;dx=np.array(r['tcp_position'])-x0;R=np.array(r['tcp_quaternion_wxyz']); dr=rotvec(qmul(R,qinv(R0)))
 print(j,'dq',np.round(dq,3),'dx',np.round(dx,3),'dr',np.round(dr,3));robot.step(list(q0)+[.04,.04])
print('end',np.round(robot.observe()['robot']['tcp_position'],3),robot.status())
